//! Status bar / system tray icon. Keeps the app reachable while its window is
//! hidden (closing the window hides it; only "Quit" exits). Its icon, and the
//! window icon, follow the blocking status; the PNGs under `icons/status/` are
//! generated by `scripts/generate-icons.sh`.

use std::thread;
use std::time::Duration;

use serde::Deserialize;
use tauri::image::Image;
use tauri::menu::{Menu, MenuItem, PredefinedMenuItem};
use tauri::tray::TrayIconBuilder;
use tauri::{AppHandle, Manager};

use crate::hosts;
use crate::ipc::{self, Request};

const TRAY_ID: &str = "main";
const MENU_TOGGLE: &str = "toggle";
const MENU_OPEN: &str = "open";
const MENU_QUIT: &str = "quit";

#[derive(Clone, Copy, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Status {
    /// Daemon not connected yet (or unreachable).
    Inactive,
    Blocked,
    /// Free Mode unblock countdown is running.
    Unblocking,
    Unblocked,
}

impl Status {
    fn icon(self) -> tauri::Result<Image<'static>> {
        Image::from_bytes(match self {
            Status::Inactive => include_bytes!("../icons/status/inactive.png"),
            Status::Blocked => include_bytes!("../icons/status/blocked.png"),
            Status::Unblocking => include_bytes!("../icons/status/unblocking.png"),
            Status::Unblocked => include_bytes!("../icons/status/unblocked.png"),
        })
    }

    fn tooltip(self) -> &'static str {
        match self {
            Status::Inactive => "Free Mind: daemon not connected",
            Status::Blocked => "Free Mind: blocking",
            Status::Unblocking => "Free Mind: unblocking…",
            Status::Unblocked => "Free Mind: not blocking",
        }
    }
}

fn status_text(blocking: bool) -> &'static str {
    if blocking {
        "Blocking is on"
    } else {
        "Blocking is off"
    }
}

fn toggle_text(blocking: bool) -> &'static str {
    if blocking {
        // Opens the window, so the unblock countdown still applies.
        "Stop Blocking…"
    } else {
        "Start Blocking"
    }
}

pub fn create(app: &AppHandle) -> tauri::Result<()> {
    let blocking = hosts::is_blocking();
    let status = MenuItem::with_id(app, "status", status_text(blocking), false, None::<&str>)?;
    let toggle = MenuItem::with_id(app, MENU_TOGGLE, toggle_text(blocking), true, None::<&str>)?;
    let open = MenuItem::with_id(app, MENU_OPEN, "Open Free Mind", true, None::<&str>)?;
    let quit = MenuItem::with_id(app, MENU_QUIT, "Quit Free Mind", true, None::<&str>)?;
    let menu = Menu::with_items(
        app,
        &[
            &status,
            &toggle,
            &PredefinedMenuItem::separator(app)?,
            &open,
            &PredefinedMenuItem::separator(app)?,
            &quit,
        ],
    )?;

    TrayIconBuilder::with_id(TRAY_ID)
        .icon(Status::Inactive.icon()?)
        .tooltip(Status::Inactive.tooltip())
        .menu(&menu)
        .show_menu_on_left_click(true)
        .on_menu_event(|app, event| match event.id().as_ref() {
            MENU_TOGGLE => toggle_blocking(app),
            MENU_OPEN => show_main_window(app),
            MENU_QUIT => app.exit(0),
            _ => {}
        })
        .build(app)?;

    // Keep the menu in sync with the hosts file, whoever changed it.
    thread::spawn(move || {
        let mut shown = blocking;
        loop {
            thread::sleep(Duration::from_secs(1));
            let now = hosts::is_blocking();
            if now != shown {
                let _ = status.set_text(status_text(now));
                let _ = toggle.set_text(toggle_text(now));
                shown = now;
            }
        }
    });
    Ok(())
}

/// Starts blocking directly. Stopping goes through the window instead, so the
/// unblock countdown can't be skipped from the tray.
fn toggle_blocking(app: &AppHandle) {
    if hosts::is_blocking() {
        show_main_window(app);
        return;
    }
    let app = app.clone();
    // Off the main thread: the daemon round trip shouldn't stall the menu.
    thread::spawn(move || {
        let request = Request::Block {
            domains: crate::enabled_domains(),
        };
        if let Err(e) = ipc::send(&request) {
            eprintln!("tray: failed to start blocking: {e}");
            // Most likely the daemon isn't installed; the window handles that.
            show_main_window(&app);
        }
    });
}

pub fn show_main_window(app: &AppHandle) {
    if let Some(window) = app.get_webview_window("main") {
        let _ = window.show();
        let _ = window.unminimize();
        let _ = window.set_focus();
    }
}

/// Swaps the tray icon and the window (taskbar) icon. macOS ignores window
/// icons, so there only the tray changes.
pub fn set_status(app: &AppHandle, status: Status) -> tauri::Result<()> {
    let icon = status.icon()?;
    if let Some(tray) = app.tray_by_id(TRAY_ID) {
        tray.set_icon(Some(icon.clone()))?;
        tray.set_tooltip(Some(status.tooltip()))?;
    }
    if let Some(window) = app.get_webview_window("main") {
        window.set_icon(icon)?;
    }
    Ok(())
}
